"""Belarus page copy and the existing CMS block keys used to store it.

Contact data was read from itwebs.by during the initial source review.
No legal entity, office, partner badges, testimonials or company metrics are inferred.
"""


def text(value):
    return {'text': value, 'href': None, 'mediaId': None, 'published': bool(value)}


def link(label, href):
    return {'text': label, 'href': href, 'mediaId': None, 'published': True}


def block(key, title, kind, fields=None, items=None):
    fields = {k: v if isinstance(v, dict) else text(v) for k, v in (fields or {}).items()}
    items = [{k: v if isinstance(v, dict) else text(v) for k, v in row.items()} for row in (items or [])]
    def rules(values):
        return {key: {'label': key, 'type': 'LINK' if value.get('href') else 'TEXT'} for key, value in values.items()}
    row_rules = {}
    for row in items:
        row_rules.update(rules(row))
    return {'key': key, 'title': title, 'type': kind,
        'schema': {'fields': rules(fields), 'itemFields': row_rules},
        'data': {'fields': fields, 'items': items}}


def page(slug, path, title, description, blocks, collections=None):
    return {'slug': slug, 'path': path, 'title': title, 'seoTitle': title + ' — ITWEBS',
        'seoDescription': description, 'canonical': None if slug == 'shared' or ':' in path else path,
        'blocks': blocks, 'collections': collections or []}


def collection(key, kind, refs=None):
    return {'key': key, 'kind': kind, 'refs': refs, 'allEntries': refs is None}


